  | { type: "file"; name: string; content: string }
  | {
      type: "tool-call";
      toolCallId: string;
      toolName: string;
      args: Record<string, unknown>;
    }
  | {
      type: "tool-call-streaming-start";
      toolCallId: string;
      toolName: string;
    }
  | {
      type: "tool-call-delta";
      toolCallId: string;
      toolName: string;
      argsTextDelta: string;
    }
  | { type: "tool-result"; toolCallId: string; result: unknown }
  | {
      type: "step-start";
      messageId: string;
      request: any;
      warnings: any[];
    }
  | {
      type: "step-finish";
      messageId: string;
      request: any;
      response: any;
      usage: {
        promptTokens: number;
        completionTokens: number;
        totalTokens: number;
      };
      finishReason: string;
    }
  | {
      type: "finish";
      finishReason: string;
      usage: {
        promptTokens: number;
        completionTokens: number;
